const main=document.querySelector('main');
const button=(href,label,primary=false)=>`<a ${href.endsWith('.pdf')?'download':''} class="button ${primary?'primary':''}" href="${href}">${label}</a>`;
const external=(url,label)=>`<a class="button primary" href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const card=p=>`<a class="project-card" href="#/project/${p.id}"><div class="thumb"><img src="assets/${p.image}" alt="${p.name} live browser screenshot" loading="lazy"><span>${p.type}</span></div><div class="card-top"><h2>${p.name}</h2><span>View project</span></div><p>${p.intro}</p></a>`;
const heading=(label,title,text)=>`<div class="page-head"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${text}</p></div>`;
const exp=()=>experience.map(e=>`<article class="experience"><time>${e[0]}</time><h2>${e[2]}</h2><h3>${e[1]}</h3><ul>${e.slice(3).map(t=>`<li>${t}</li>`).join('')}</ul></article>`).join('');
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">Ahmad Fadzil / Creative leader & game maker</span><h1>Clear vision.<br><em>Playable</em><br><em>worlds.</em></h1><p>I connect creative direction, hands-on development and production leadership to bring games from an idea to a shared experience.</p><div class="actions">${button('#/work','Explore selected work',true)}${button('#/solo','Play solo projects')}</div></div><div class="scene-shell cube-shell" id="scene" role="region" aria-label="Playable Rubik’s cube"></div><span class="side-label">BASED IN MALAYSIA / OPEN TO GAME DIRECTOR ROLES</span></section>
 <div class="stats"><div class="stat"><strong>17+ years</strong><span>Games & animation experience</span></div><div class="stat"><strong>40–45</strong><span>Staff in coordinated studio production</span></div><div class="stat"><strong>Vision to play</strong><span>Creative, technical & production practice</span></div></div>
 <section class="section"><div class="section-heading"><div><span class="eyebrow">Independent development / Featured project</span><h2>Ideas made playable.</h2></div><a class="text-link" href="#/solo">Explore all solo projects</a></div><article class="featured"><a class="featured-image" href="#/project/police-n-thief"><img src="assets/police-n-thief.jpg" alt="Police N Thief colourful Three.js character and game menu"></a><div class="featured-copy"><div class="tags"><span class="tag">Solo development</span><span class="tag">Multiplayer</span><span class="tag">Three.js</span></div><h3>Police N Thief</h3><p>Asymmetric chase. Shared chaos. A party-game prototype built from gameplay rules and AI through to interface, multiplayer and playable delivery.</p>${button('#/project/police-n-thief','Explore the project')}</div></article></section>
 <section class="section"><div class="section-heading"><div><span class="eyebrow">Leadership in practice</span><h2>Direction with delivery.</h2></div><a class="text-link" href="#/cv">Read my experience</a></div><div class="leadership"><p>My career has moved from building worlds to shaping their creative direction and coordinating the teams that deliver them. I bring the perspective of an artist, a technical collaborator and a producer to game leadership.</p><div class="principles"><div><h3>Define a shared creative vision</h3><p>Art briefs, world-building and early hero gameplay concepts at Todak Studios.</p></div><div><h3>Connect creative and technical decisions</h3><p>Technical art direction at Studio Kamii and commercial co-development experience at Virtuos.</p></div><div><h3>Make the next milestone achievable</h3><p>Production planning, team alignment, resource visibility and structured playtesting.</p></div></div></div><div class="credit-line"><span>Todak Studios</span><span>Virtuos Kuala Lumpur</span><span>Studio Kamii</span><span>Animonsta</span></div></section>
 <section class="section cta"><div><span class="eyebrow">The next chapter</span><h2>Let’s build something<br>worth playing.</h2><p>I’m interested in Game Director opportunities where creative judgement, multidisciplinary collaboration and practical delivery matter.</p></div>${button('#/contact','Start a conversation',true)}</section>`;}
function work(){return heading('Professional work / Selected contributions','Creative intent.<br>Production craft.','A selection of studio projects and leadership responsibilities. Each credit describes my specific contribution.')+`<div class="page-content"><div class="studio-art"><span>TODAK STUDIOS / CREATIVE DIRECTION</span><strong>Mastra<br>Battle Arena</strong></div><article class="work-row"><div><span class="eyebrow">Todak Studios · 2022–2024</span><h2>Mastra Battle Arena</h2><p class="role">Creative Director</p></div><div><h3>A creative vision a team can act on.</h3><p>Set creative direction, visual identity, art briefs and review standards. Guided world-building and early gameplay design, including individual hero mechanics.</p><p>Translated creative intent into production priorities through multidisciplinary reviews, feedback and technical guidance.</p></div></article><article class="work-row"><div><h2>Mastra Opening Trailer</h2><p class="role">Cinematic creative contribution</p></div><div><p>Helped shape visual storytelling, shot composition, camera framing, cinematic pacing and editing choices, maintaining consistency with the game’s artistic direction.</p></div></article><article class="work-row"><div><span class="eyebrow">Todak Studios · 2025–Present</span><h2>Studio delivery</h2><p class="role">Producer / Project Manager</p></div><div><h3>Aligning people, resources and milestones.</h3><p>Coordinate production involving 40–45 employees across internal and external projects. Track progress, forecast milestones, allocate resources and escalate risks.</p><p>Support candidate reviews and interviews, voice-acting auditions and structured QA playtests informed by Six Sigma practices.</p></div></article><article class="work-row"><div><span class="eyebrow">Virtuos Kuala Lumpur · 2021–2022</span><h2>Commercial co-development</h2><p class="role">3D Artist</p></div><div><h3>Medal of Honor: Above and Beyond / CrossFire HD</h3><p>3D asset production within commercial game-development pipelines, including VR optimization work. These are art-production credits.</p></div></article><article class="work-row"><div><span class="eyebrow">Studio Kamii · 2018–2021</span><h2>Technical art leadership</h2><p class="role">Technical Art Director</p></div><div><h3>ToGather:Island / NevaLogik</h3><p>Worked with the Game Director and concept artists to bridge creative requirements and technical implementation through asset production and technical-art delivery.</p></div></article><article class="work-row"><div><span class="eyebrow">Animation foundations</span><h2>Worlds for the screen</h2></div><div><h3>BoBoiBoy: The Movie / BoBoiBoy Galaxy</h3><p>Environment art at Animonsta, with VFX and compositing contributions to the film. Earlier work includes HadiHuda animation, Hoodwink asset production and Upin & Ipin compositing.</p></div></article><div class="actions">${button('https://www.artstation.com/z_e_a_l','Explore ArtStation',true)}${button('#/cv','View full CV')}</div></div>`;}
function solo(){return heading('Independent development / Browser playables','The solo<br>project lab.','Four projects. Different systems, moods and player experiences. Explore each project, then open its live browser build.')+`<section class="page-content"><div class="grid">${projects.map(card).join('')}</div><div class="notice"><p>Also in development: <strong>Pandora</strong>, a personal deck-building action roguelite inspired by Southeast Asian folklore, connecting nighttime combat and gathering with village diagnosis, preparation and treatment.</p></div></section>`;}
function project(id){const p=projects.find(x=>x.id===id);if(!p)return missing();return `<article class="detail"><a class="breadcrumb" href="#/solo">All solo projects</a><div class="detail-top"><div><span class="eyebrow">Solo project / ${p.type}</span><h1>${p.name}</h1><p>${p.intro}</p></div><div class="actions">${external(p.url,'Play in browser')}</div></div><img class="detail-image" src="assets/${p.image}" alt="${p.name} public playable build"><div class="detail-columns"><aside><h2>Project overview</h2><dl><dt>Ownership</dt><dd>Personal / independent project</dd><dt>Focus</dt><dd>${p.focus}</dd><dt>Access</dt><dd>Public browser playable</dd></dl>${external(p.url,'Open live project')}</aside><div><h2>The experience</h2><p>${p.description}</p><h3>Scope & contribution</h3><ul>${p.contribution.map(x=>`<li>${x}</li>`).join('')}</ul><h3>Design perspective</h3><p>${p.design}</p><h3>Build context</h3><p>${p.tech}</p></div></div></article>`;}
function cv(){return heading('Experience / Professional profile','Ahmad Fadzil','Creative direction, game development and production leadership. Full name: Ahmad Fadzil Bin Ahmad Nasharuddin.')+`<section class="page-content cv-layout"><aside class="cv-aside"><h2>Vision. Craft.<br>Team delivery.</h2><p>17+ years of combined experience across games and animation, from technical art and commercial co-development to creative direction and studio production.</p>${button('assets/Ahmad-Fadzil-CV.pdf','Download CV · PDF',true)}<button class="button" id="print-cv">Print web CV</button><p>Selangor, Malaysia<br><a href="mailto:ahmadfadzil22@gmail.com">ahmadfadzil22@gmail.com</a></p><p><strong>Areas of practice</strong><br>Creative direction · Gameplay concepts · Prototyping · Technical art · Art briefs · Production planning · Multidisciplinary coordination · Recruitment · QA playtesting</p><p><a class="text-link" href="https://www.artstation.com/z_e_a_l" target="_blank" rel="noopener noreferrer">ArtStation portfolio</a></p></aside><div>${exp()}<article class="experience"><span class="eyebrow">Independent practice</span><h2>Solo development & prototyping</h2><p>Police N Thief, Combat Patrol, Potionpendium and QuantumLoom are available in the solo-project gallery. Pandora is an ongoing personal deck-building action roguelite concept.</p><div class="actions" style="margin-top:20px">${button('#/solo','Explore solo projects')}</div></article></div></section>`;}
function contact(){return `<section class="contact"><span class="eyebrow">Contact / Based in Selangor, Malaysia</span><h1>A shared vision.<br>A new world.</h1><p>Let’s discuss Game Director opportunities, creative leadership and the games your team wants to bring to life.</p><a class="contact-email" href="mailto:ahmadfadzil22@gmail.com">ahmadfadzil22@gmail.com</a><div class="contact-links"><a class="text-link" href="https://www.artstation.com/z_e_a_l" target="_blank" rel="noopener noreferrer">ArtStation</a><a class="text-link" href="assets/Ahmad-Fadzil-CV.pdf" download>Download CV</a><a class="text-link" href="#/solo">Play my projects</a></div></section>`;}
function missing(){return `<section class="error"><span class="eyebrow">Page not found</span><h1>Let’s get back to the work.</h1>${button('#/','Return to overview',true)}</section>`;}
let cleanup;
async function render(){cleanup?.();cleanup=null;const parts=(location.hash.slice(1)||'/').split('/').filter(Boolean);const page=parts[0]||'home';main.innerHTML=({home,work,solo,cv,contact}[page]||(()=>page==='project'?project(parts[1]):missing()))();document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===(page==='project'?'solo':page))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=`${page==='home'?'Game Direction & Creative Leadership':page==='project'?(projects.find(p=>p.id===parts[1])?.name||'Project'):({work:'Selected Work',solo:'Solo Projects',cv:'CV',contact:'Contact'}[page]||'Page not found')} — Ahmad Fadzil`;window.scrollTo(0,0);document.getElementById('print-cv')?.addEventListener('click',()=>window.print());if(page==='home'){try{const {createScene}=await import('./scene.js');if(document.getElementById('scene'))cleanup=createScene(document.getElementById('scene'));}catch(e){console.warn('3D scene unavailable',e);document.getElementById('motion')?.remove();}}}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
document.getElementById('year').textContent=new Date().getFullYear();window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true});});render();
